"""No watermarks or AI/Muse branding in shipped code or docs."""

from pathlib import Path

BANNED = [
    "Muse", "Claude", "Anthropic", "AI-generated", "generated by AI",
    "generated with AI", "watermark",
]

ROOT = Path(__file__).resolve().parents[1]


def test_no_branding_in_shipped_files():
    offenders = []
    for path in ROOT.rglob("*"):
        if not path.is_file():
            continue
        if ".git" in path.parts or "__pycache__" in path.parts:
            continue
        if path.suffix not in {".py", ".md", ".txt", ".toml", ".yml", ".yaml"}:
            continue
        if path.name == "test_branding.py":
            continue
        text = path.read_text(errors="ignore")
        for term in BANNED:
            if term in text:
                offenders.append(f"{path.relative_to(ROOT)}: {term}")
    assert not offenders, offenders
